BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE bat_reconciliation_audit (
    reconciliation_audit_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    request_id VARCHAR2(100) NOT NULL,
    entity_type VARCHAR2(40) NOT NULL,
    entity_key VARCHAR2(300) NOT NULL,
    from_status VARCHAR2(40) NOT NULL,
    to_status VARCHAR2(40) NOT NULL,
    requester_id VARCHAR2(120) NOT NULL,
    approver_id VARCHAR2(120) NOT NULL,
    reason_text VARCHAR2(1000) NOT NULL,
    idempotency_key VARCHAR2(200) NOT NULL,
    expected_attempt NUMBER(10),
    expected_version NUMBER(19),
    created_at TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT uq_bat_reconcile_idem UNIQUE (idempotency_key),
    CONSTRAINT ck_bat_reconcile_separation CHECK (requester_id <> approver_id))';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'CREATE INDEX ix_bat_reconcile_entity ON bat_reconciliation_audit(entity_type, entity_key, created_at)';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF;
END;
/
